command:
(() => {


	const entry = game.journal.getName("Chat Archive");
	if (!entry) {
		ui.notifications.warn("No 'Chat Archive' found.");
		return;
	}
	let journalData = "";
	let totalChars = 0, pages = 0;
	for (const p of entry.pages) {
		const len = p.text?.content?.length ?? 0;
		pages++;
		journalData += `${p.name}: ${(len / 1024).toFixed(1)} KB \n`
		console.log(`${p.name}: ${(len / 1024).toFixed(1)} KB`);
		totalChars += len;
	}
	journalData += `Total pages: ${pages}, Total size: ${(totalChars / 1024).toFixed(1)} KB`
	console.log(`Total pages: ${pages}, Total size: ${(totalChars / 1024).toFixed(1)} KB`);

	const html = `
	<div style="min-width: 700px; min-height: 500px; padding-right: 1em;">
		<textarea id="module-list-textarea"
		style="width: 680px; height: 450px; font-family: monospace; resize: none; box-sizing: border-box;"
		readonly
		autofocus
		>${journalData}</textarea>
	</div>
	`;

	const dialog = new foundry.applications.api.DialogV2({
		window: {
			title: "Chat Archive Size Report",
			width: 800,
			height: 600,
			resizable: true
		},
		content: html,
		buttons: [
			{
				action: "close",
				label: "Close",
				default: true
			}
		]
	});

	dialog.render(true);
})();
